package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import java.util.concurrent.*;import app.layan.quran.*;
/** Real native root-task removal, followed by an independent cold audio observer. */
public final class TaskRemovalRegression extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();Activity a=startActivitySync(new Intent().setClassName(c,"app.layan.quran.LayanInfoActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));SharedPreferences prefs=android.preference.PreferenceManager.getDefaultSharedPreferences(c),state=c.getSharedPreferences("layan_dhikr_schedule",0);runOnMainSync(()->{prefs.edit().putBoolean(DhikrReminder.ENABLED,false).commit();prefs.edit().putString(DhikrReminder.INTERVAL,"5").putBoolean(DhikrReminder.SILENT,true).putBoolean(DhikrReminder.ENABLED,true).commit();});android.media.AudioManager audio=c.getSystemService(android.media.AudioManager.class);Vibrator vibrator=c.getSystemService(Vibrator.class);int mutedMode=vibrator!=null&&vibrator.hasVibrator()?android.media.AudioManager.RINGER_MODE_VIBRATE:android.media.AudioManager.RINGER_MODE_SILENT;getUiAutomation().adoptShellPermissionIdentity("android.permission.MODIFY_AUDIO_SETTINGS","android.permission.ACCESS_NOTIFICATION_POLICY");try{audio.setRingerMode(mutedMode);audio.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,audio.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC),0);}finally{getUiAutomation().dropShellPermissionIdentity();}long modeDeadline=SystemClock.elapsedRealtime()+5000;while(audio.getRingerMode()==android.media.AudioManager.RINGER_MODE_NORMAL&&SystemClock.elapsedRealtime()<modeDeadline)SystemClock.sleep(50);out.putInt("actualRingerMode",audio.getRingerMode());out.putBoolean("virtualVibratorAvailable",vibrator!=null&&vibrator.hasVibrator());if(audio.getRingerMode()!=android.media.AudioManager.RINGER_MODE_VIBRATE&&audio.getRingerMode()!=android.media.AudioManager.RINGER_MODE_SILENT)throw new AssertionError("Actual muted ringer fixture missing");long next=state.getLong("next",0);String token=state.getString("token","");if(next<=SystemClock.elapsedRealtime()||token.isEmpty())throw new AssertionError("Real selected alarm missing");int task=a.getTaskId();CountDownLatch removed=new CountDownLatch(1);a.getApplication().registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity x,Bundle b){}public void onActivityStarted(Activity x){}public void onActivityResumed(Activity x){}public void onActivityPaused(Activity x){}public void onActivityStopped(Activity x){}public void onActivitySaveInstanceState(Activity x,Bundle b){}public void onActivityDestroyed(Activity x){if(x==a)removed.countDown();}});runOnMainSync(a::finishAndRemoveTask);if(!removed.await(30,TimeUnit.SECONDS))throw new AssertionError("Native removal lifecycle missing");for(ActivityManager.AppTask t:c.getSystemService(ActivityManager.class).getAppTasks())if(t.getTaskInfo().taskId==task)throw new AssertionError("Task remains in native recents");if(state.getLong("next",0)!=next||!token.equals(state.getString("token","")))throw new AssertionError("Task removal changed selected alarm");out.putInt("actualRingerMode",audio.getRingerMode());out.putBoolean("virtualVibratorAvailable",vibrator!=null&&vibrator.hasVibrator());out.putLong("next",next);out.putString("result","PASS real root task removed; persisted alarm deadline and token retained unchanged");finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
